var seed = Math.random() * 15283;
var t;
var num, vNum;
var radius, mySize, margin;
var sizes = [];

let palette;
let color_bg;
let v_planet = [];

function setup() {
	frameRate(50);
	randomSeed(seed);
	// pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
	margin = mySize / 100;
	createCanvas(windowWidth, windowHeight, WEBGL);
	perspective(PI / 4.5, width / height, 1, 5000);

	palette = random(colorScheme).colors.concat();
	color_bg = "#202020";
	color_bg = random(palette);
	background(color_bg);
	num = int(random(20, 10));
	radius = mySize * 2.25;
	for (let a = 0; a < TAU; a += TAU / num) {
		sizes.push(random(0.1, 0.5))
	}
	t = 0;
	makeFilter();
}

function draw() {
	randomSeed(seed);
	// orbitControl();
	// background(color_bg);

	for (let i = 0; i < num; i++) {
		let a = (TAU / num) * i;
		let x = radius * sin(a + t) / random(5, 3) / 1.0;
		let y = radius * cos(a + t) / random(3, 5) / 1.0;
		v_planet[i] = createVector(x, y);
	}
	push();

	for (let q = 0; q < 1 / 5; q += 2 * random(0.01, 0.02)) {
		for (let j = 0; j < 1; j++) {
			let n = noise(q * t, j * t, frameCount * 0.01);
			rotateX(random(TAU) + sin(-t) / 5 + q);
			rotateY(random(TAU) + cos(t) / 5 + q);
			rotateZ(random(TAU) + sin(-t) / 5 + q);
			noStroke();
			fill(random(palette));

			for (let i = 0; i < num; i += 8) {
				let d = random(radius / 2, radius / 4) / 1;
				push();
				rotateX(random(TAU) + sin(t));
				rotateY(random(TAU) + cos(-t) + n / 100);
				rotateZ(random(TAU) + 2 * sin(2 * t));
				let x_plus = 1.25 * random(-d, d) / 1;
				let y_plus = 1.25 * random(-d, d) / 1;
				let z_plus = 1.25 * random(-d, d) / 1;
				torus(z_plus, random(0.5), 100, 100);
				pop();
			}
			for (let i = 0; i < num; i += 4) {
				var d = (1.5 + sin(t)) * random(radius / 2, radius / 4);
				var x_plus = 0.5 * random(-d, d) / 1;
				var y_plus = 0.5 * random(-d, d) / 1;
				var z_plus = 0.5 * random(-d, d) / 1;
				stroke(random(palette));
				strokeWeight(random(0.1, 1.5));
				noFill();
				push();
				translate(v_planet[i].x + x_plus, v_planet[i].y + y_plus, z_plus);
				rotateX(random(TAU) + t);
				rotateY(random(-TAU) + t);
				rotateZ(random(PI) + t);
				sphere(random(2, 15));
				pop();
			}
		}
	}
	pop();
	image(overAllTexture, -width/2, -height/2, width, height);
	t += random(2, 1) * random(0.001, 0.005) / 1;
}

